private fun uriBase64(context:Context,uriText:String):String{if(uriText.isBlank())return "";return try{context.contentResolver.openInputStream(Uri.parse(uriText))?.use{android.util.Base64.encodeToString(it.readBytes(),android.util.Base64.NO_WRAP)}?:""}catch(_:Exception){""}}
private fun restoreImage(context:Context,encoded:String,fallback:String):String{if(encoded.isBlank())return fallback;return try{val dir=java.io.File(context.filesDir,"backup_media").apply{mkdirs()};val f=java.io.File(dir,"img_${System.currentTimeMillis()}_${(0..9999).random()}.jpg");f.writeBytes(android.util.Base64.decode(encoded,android.util.Base64.DEFAULT));android.net.Uri.fromFile(f).toString()}catch(_:Exception){fallback}}
private suspend fun refreshWidgets(context:Context){try{val manager=GlanceAppWidgetManager(context);manager.getGlanceIds(VehicleWidget::class.java).forEach{VehicleWidget().update(context,it)}}catch(_:Exception){}}
private fun periodLabel(p:String,m:String,y:String)=when(p){"Bulan"->m;"Tahun"->y;"Rentang"->"$m – $y";else->"Semua waktu"}
private fun backupJson(context:Context,vs:List<Vehicle>,es:List<EntryRecord>,user:String):String{val root=JSONObject().put("app","GarasiKu").put("version",2).put("user",user);val va=JSONArray();vs.forEach{va.put(JSONObject().put("id",it.id).put("name",it.name).put("plate",it.plate).put("type",it.type).put("photo",it.photo).put("photoBase64",uriBase64(context,it.photo)).put("currentKm",it.currentKm).put("oilInterval",it.oilInterval).put("lastOilKm",it.lastOilKm).put("serviceInterval",it.serviceInterval).put("lastServiceKm",it.lastServiceKm).put("taxDate",it.taxDate).put("notes",it.notes))};val ea=JSONArray();es.forEach{ea.put(JSONObject().put("id",it.id).put("vehicleId",it.vehicleId).put("date",it.date).put("category",it.category).put("itemName",it.itemName).put("amount",it.amount).put("km",it.km).put("liters",it.liters).put("station",it.station).put("note",it.note).put("receiptPhoto",it.receiptPhoto).put("receiptBase64",uriBase64(context,it.receiptPhoto)))};return root.put("vehicles",va).put("entries",ea).toString(2)}
private suspend fun restoreJson(context:Context,raw:String,dao:GarageDao){val root=JSONObject(raw);val vs=root.getJSONArray("vehicles");val es=root.getJSONArray("entries");dao.clearEntries();dao.clearVehicles();for(i in 0 until vs.length()){val o=vs.getJSONObject(i);dao.addVehicle(Vehicle(name=o.optString("name"),plate=o.optString("plate"),type=o.optString("type","Motor"),photo=restoreImage(context,o.optString("photoBase64"),o.optString("photo")),currentKm=o.optLong("currentKm"),oilInterval=o.optLong("oilInterval",2500),lastOilKm=o.optLong("lastOilKm"),serviceInterval=o.optLong("serviceInterval",5000),lastServiceKm=o.optLong("lastServiceKm"),taxDate=o.optString("taxDate"),notes=o.optString("notes")))};val newVs=dao.allVehicles();for(i in 0 until es.length()){val o=es.getJSONObject(i);val oldId=o.optLong("vehicleId");val vehicleIndex=(0 until vs.length()).firstOrNull{vs.getJSONObject(it).optLong("id")==oldId}?:0;dao.addEntry(EntryRecord(vehicleId=newVs.getOrNull(vehicleIndex)?.id?:newVs.firstOrNull()?.id?:0,date=o.optString("date"),category=o.optString("category"),itemName=o.optString("itemName"),amount=o.optLong("amount"),km=o.optLong("km"),liters=o.optDouble("liters"),station=o.optString("station"),note=o.optString("note"),receiptPhoto=restoreImage(context,o.optString("receiptBase64"),o.optString("receiptPhoto"))))}}
private fun openEntry(old:EntryRecord?,cat:String,vehicles:List<Vehicle>,eVehicleSetter:(Long)->Unit,nameSetter:(String)->Unit,amountSetter:(String)->Unit,kmSetter:(String)->Unit,litersSetter:(String)->Unit,categorySetter:(String)->Unit,dateSetter:(String)->Unit,noteSetter:(String)->Unit,stationSetter:(String)->Unit,receiptSetter:(String)->Unit,showSetter:()->Unit){eVehicleSetter(old?.vehicleId?:vehicles.firstOrNull()?.id?:0);nameSetter(old?.itemName?:"");amountSetter(old?.amount?.toString()?:"");kmSetter(old?.km?.toString()?:"");litersSetter(old?.liters?.toString()?:"");categorySetter(old?.category?:cat);dateSetter(old?.date?:LocalDate.now().toString());noteSetter(old?.note?:"");stationSetter(old?.station?:"");receiptSetter(old?.receiptPhoto?:"");showSetter()}
@Composable private fun ActionTile(title:String,icon:androidx.compose.ui.graphics.vector.ImageVector,onClick:()->Unit){Card(Modifier.width(105.dp).clickable{onClick()},shape=RoundedCornerShape(14.dp)){Column(Modifier.padding(12.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(icon,null,tint=blue);Text(title,fontSize=12.sp)}}}
@Composable private fun VehicleCard(v:Vehicle,records:List<EntryRecord>,onClick:()->Unit,onEdit:(()->Unit)?=null,onDelete:(()->Unit)?=null){val latest=records.filter{it.category=="BBM"}.maxByOrNull{it.date};Card(Modifier.fillMaxWidth().padding(vertical=6.dp).clickable{onClick()},shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(14.dp)){if(v.photo.isNotBlank())AsyncImage(model=v.photo,contentDescription="Foto ${v.name}",modifier=Modifier.fillMaxWidth().height(150.dp));Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(v.name,fontSize=18.sp,fontWeight=FontWeight.Bold);Text(v.plate,color=Color.Gray)};if(onEdit!=null)IconButton(onClick=onEdit){Icon(Icons.Default.Edit,null)};if(onDelete!=null)IconButton(onClick=onDelete){Icon(Icons.Default.Delete,null,color=Color.Red)}};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){AssistChip(onClick={},label={Text("KM ${v.currentKm}")});AssistChip(onClick={},label={Text("Oli ${(v.lastOilKm+v.oilInterval-v.currentKm).coerceAtLeast(0)} km lagi")});AssistChip(onClick={},label={Text("Servis ${(v.lastServiceKm+v.serviceInterval-v.currentKm).coerceAtLeast(0)} km lagi")})};Text("BBM terakhir: ${latest?.let{rupiah(it.amount)}?:"Belum ada"}");Text("Ganti oli pada ${v.lastOilKm+v.oilInterval} km",color=orange,fontWeight=FontWeight.SemiBold)}}}
@Composable private fun EntryCard(e:EntryRecord,v:Vehicle?,onEdit:()->Unit,onDelete:()->Unit){Card(Modifier.fillMaxWidth().padding(vertical=4.dp)){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(e.itemName,fontWeight=FontWeight.Bold);Text("${e.category} · ${e.date} · ${v?.name?:"Kendaraan"}",fontSize=12.sp,color=Color.Gray);if(e.note.isNotBlank())Text(e.note,fontSize=12.sp,color=Color.Gray)};Column(horizontalAlignment=Alignment.End){Text(rupiah(e.amount),fontWeight=FontWeight.Bold);Row{IconButton(onClick=onEdit){Icon(Icons.Default.Edit,null)};IconButton(onClick=onDelete){Icon(Icons.Default.Delete,null,color=Color.Red)}}}}}}
